    relationRoot.innerHTML='<label>'+(zh?'预设关系':'Preset relation')+' <select data-relation-preset></select></label><div class="relation-grid" role="group" aria-label="'+(zh?'关系表，行是第一坐标':'Relation table, rows are first coordinates')+'"></div><div class="relation-status" role="status" aria-live="polite"></div>';
    var preset=relationRoot.querySelector('select'),grid=relationRoot.querySelector('.relation-grid');
