      var witnesses={reflexive:null,symmetric:null,antisymmetric:null,transitive:null};
      for(var x=0;x<3;x++){
        if(!entries[x*3+x]&&!witnesses.reflexive)witnesses.reflexive=[x,x];
        for(var y=0;y<3;y++){
          if(entries[x*3+y]&&!entries[y*3+x]&&!witnesses.symmetric)witnesses.symmetric=[x,y];
          if(x!==y&&entries[x*3+y]&&entries[y*3+x]&&!witnesses.antisymmetric)witnesses.antisymmetric=[x,y];
          for(var z=0;z<3;z++)if(entries[x*3+y]&&entries[y*3+z]&&!entries[x*3+z]&&!witnesses.transitive)witnesses.transitive=[x,y,z];
        }
      }
      var propertyLabels=zh?{reflexive:'自反',symmetric:'对称',antisymmetric:'反对称',transitive:'传递'}:{reflexive:'Reflexive',symmetric:'Symmetric',antisymmetric:'Antisymmetric',transitive:'Transitive'};
      relationRoot.querySelector('.relation-status').innerHTML=Object.keys(witnesses).map(function(key){return '<p data-property="'+key+'">'+propertyLabels[key]+': '+(witnesses[key]?(zh?'失败，见证 ':'fails; witness ')+'('+witnesses[key].join(',')+')':(zh?'成立':'holds'))+'</p>';}).join('');
