      status.textContent=(zh?'精确计数：':'Exact count: ')+count+'. '+(zh?'展示前 ':'Showing first ')+shown.length+(zh?' 个结果；样例展示不是全部枚举的声明。':' outcomes; the displayed sample is not a claim of full enumeration.');
