    var aControl=recurrenceRoot.querySelector('select'),hControl=recurrenceRoot.querySelector('input');
    function recurrenceUpdate(){
      var a=Number(aControl.value),h=Number(hControl.value),status=recurrenceRoot.querySelector('.recurrence-status'),tbody=recurrenceRoot.querySelector('tbody');
      if(hControl.value===''||!Number.isInteger(h)||h<0||h>8){status.textContent=zh?'h 必须是 0–8 的整数。':'h must be an integer from 0–8.';tbody.innerHTML='';recurrenceRoot.dataset.total='invalid';return;}
      var n=2**h,total=0,rows=[];
      for(var j=0;j<=h;j++){var nodes=a**j,size=n/2**j,cost=nodes*size;total+=cost;rows.push('<tr><th scope="row">'+j+(j===h?(zh?'（叶）':' (leaves)'):'')+'</th><td>'+nodes+'</td><td>'+size+'</td><td>'+cost+'</td></tr>');}
      tbody.innerHTML=rows.join('');status.textContent='n = '+n+'; T('+n+') = '+total+'. '+(zh?'非叶节点收费为其大小；单位叶也计入总和。':'A nonleaf costs its size; unit-cost leaves are included in the sum.');recurrenceRoot.dataset.total=total;
    }
