      var first=Math.abs(a),second=m,trace=[];while(second){var quotient=Math.floor(first/second),remainder=first%second;trace.push(first+'='+quotient+'×'+second+'+'+remainder);first=second;second=remainder;}
      var output=mod(operationControl.value==='add'?a+x:a*x,m);status.textContent=(operationControl.value==='add'?a+' + '+x:a+' × '+x)+' ≡ '+output+' (mod '+m+'); gcd('+a+','+m+')='+first+'; '+(zh?'乘法逆：':'multiplicative inverse: ')+(inverse===null?(zh?'不存在':'none'):inverse)+'.';
      residueRoot.querySelector('.residue-map').textContent=(zh?'乘法映射：':'Multiplication map: ')+mapping.join(', ');residueRoot.querySelector('.residue-euclid').textContent=(zh?'欧几里得（先取 |a|）：':'Euclid (starting with |a|): ')+trace.join('; ');
      var clock='<circle cx="220" cy="160" r="112" fill="none" stroke="#cbd5e1"/>';
      for(var i=0;i<m;i++){var angle=2*Math.PI*i/m-Math.PI/2,cx=220+112*Math.cos(angle),cy=160+112*Math.sin(angle);clock+='<circle cx="'+cx+'" cy="'+cy+'" r="17" fill="'+(i===output?'#dbeafe':'white')+'" stroke="'+(i===output?'#2563eb':'#64748b')+'"/><text x="'+cx+'" y="'+(cy+5)+'" text-anchor="middle">'+i+'</text>';}
      clock+='<text x="220" y="165" text-anchor="middle">mod '+m+'</text>';residueRoot.querySelector('svg').innerHTML=clock;residueRoot.dataset.inverse=inverse===null?'none':inverse;residueRoot.dataset.result=output;residueRoot.dataset.gcd=first;
